424	+// A finalize landing anywhere in a rebuild must not fail it, and whatever gets
425	+// published must describe one version of the transcript: the index and the
426	+// receipts attesting to it cannot disagree about which bytes were processed.
427	+func TestHistoryRebuildSurvivesCheckpointFinalize(t *testing.T) {
428	+	const withManifestUpdate = "alongside an unrelated manifest update"
429	+	afterBuild := func(fire func()) (historyIndexProgress, func()) {
430	+		return func(done, total int) {
431	+			if total > 0 && done == total {
432	+				fire()
433	+			}
434	+		}, func() {}
435	+	}
436	+	windows := map[string]func(fire func()) (historyIndexProgress, func()){
437	+		"after the build read the transcript, before receipts": afterBuild,
438	+		withManifestUpdate: afterBuild,
439	+		"before the post-scan identity check": func(fire func()) (historyIndexProgress, func()) {
440	+			original := beforeHistoryProjectionContentDigest
441	+			beforeHistoryProjectionContentDigest = func(string) { fire() }
442	+			return nil, func() { beforeHistoryProjectionContentDigest = original }
443	+		},
444	+	}
445	+	for name, window := range windows {
446	+		t.Run(name, func(t *testing.T) {
447	+			opts, brain, repo := filelessCheckpointFixture(t)
448	+			runFilelessExport(t, opts, "", true)
449	+			finalized := ""
450	+			progress, restore := window(func() {
451	+				if finalized == "" {
452	+					finalized = finalizeCheckpointTranscript(t, repo)
453	+					if name == withManifestUpdate {
454	+						// Touches the manifest without changing any session.
455	+						manifest, err := bmanifest.Load(brain)
456	+						if err != nil {
457	+							t.Fatal(err)
458	+						}
459	+						if err := writeBrainManifestAndReadme(brain, *manifest); err != nil {
460	+							t.Fatal(err)
461	+						}
462	+					}
463	+				}
464	+			})
465	+			defer restore()
466	+
467	+			now := opts.Now().Add(time.Minute)
468	+			prepared, err := prepareBrainHistoryProjection(brain, now, progress)
469	+			if err != nil {
470	+				t.Fatalf("rebuild lost to a checkpoint finalize: %v", err)
471	+			}
472	+			restore()
473	+			if finalized == "" {
474	+				t.Fatal("the finalize never fired, so this window proves nothing")
475	+			}
476	+			if strings.Contains(mustMarshalIndex(t, prepared.index), finalizedMarker) {
477	+				t.Fatal("index contains finalized bytes the rebuild's identity does not describe")
478	+			}
479	+			if _, err := publishBrainHistoryProjectionLocked(brain, prepared, nil); err != nil {
480	+				t.Fatalf("publish: %v", err)
481	+			}
482	+			assertReceiptDigest(t, brain, transcriptTestDigest(conversationClaudeFixture))
483	+
484	+			// Nothing is lost, exactly as if the finalize had landed just after
485	+			// publish: the index reads as stale, the next delta serves the new
486	+			// bytes, and the next rebuild absorbs them.
487	+			manifest, err := bmanifest.Load(brain)
488	+			if err != nil {
489	+				t.Fatal(err)
490	+			}
491	+			if historyIndexCurrent(brain, manifest) {
492	+				t.Fatal("index reads as current after its transcript was finalized")
493	+			}
494	+			if _, err := buildHistoryShortTermLocked(brain, now.Add(time.Minute)); err != nil {
495	+				t.Fatalf("delta: %v", err)
496	+			}
497	+			overlay, _ := loadHistoryShortTermRaw(brain)
498	+			overlayData, err := json.Marshal(overlay)
499	+			if err != nil {
500	+				t.Fatal(err)
501	+			}
502	+			if !strings.Contains(string(overlayData), finalizedMarker) {
503	+				t.Fatal("the next delta did not pick up the finalized transcript")
504	+			}
505	+			if _, err := writeBrainHistoryIndexAndSourceLocked(brain, now.Add(2*time.Minute), nil); err != nil {
506	+				t.Fatalf("next rebuild: %v", err)
507	+			}
508	+			assertReceiptDigest(t, brain, transcriptTestDigest(finalized))
509	+			manifest, err = bmanifest.Load(brain)
510	+			if err != nil {
511	+				t.Fatal(err)
512	+			}
513	+			index, err := historystore.LoadIndex(brain, manifest.Sources.History)
514	+			if err != nil {
515	+				t.Fatal(err)
516	+			}
517	+			if !strings.Contains(mustMarshalIndex(t, index), finalizedMarker) {
518	+				t.Fatal("the next rebuild did not pick up the finalized transcript")
519	+			}
520	+		})
521	+	}
522	+}
